OUT = "palabritas-voices"

async def one(job, voices, sem, done):
    lang, text, speed, name = job
    path = os.path.join(OUT, name)
    if os.path.exists(path) and os.path.getsize(path) > 1000:
        return
    rate = f"{round((speed - 1) * 100) - (8 if lang == 'es' else 0):+d}%"   # a little slower for little ears
    for attempt in range(4):
        async with sem:
            try:
                await edge_tts.Communicate(text, voices[lang], rate=rate).save(path + ".part")
                os.replace(path + ".part", path); done.append(name)
                if len(done) % 50 == 0: print(f"  {len(done)} made")
                return
            except Exception as e:
                err = e
        await asyncio.sleep(2 * (attempt + 1))
    print("could not make:", text, "-", err)

async def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--sample", action="store_true")
    ap.add_argument("--es", default="es-US-PalomaNeural")
    ap.add_argument("--en", default="en-US-JennyNeural")
    a = ap.parse_args()
    os.makedirs(OUT, exist_ok=True)
    jobs = JOBS
    if a.sample:
        want = {"hola", "cinco", "gracias", "La zanahoria es naranja.", "Let's learn some Spanish!", "Tap the house to go back."}
        jobs = [j for j in JOBS if j[1] in want]
    sem, done = asyncio.Semaphore(4), []
    print(f"Making {len(jobs)} clips with {a.es} and {a.en} ...")
    await asyncio.gather(*(one(j, {"es": a.es, "en": a.en}, sem, done) for j in jobs))
    missing = [j for j in jobs if not os.path.exists(os.path.join(OUT, j[3]))]
    if a.sample:
        print(f"Done. Listen in the folder {OUT}/"); return
    if missing:
        print(f"{len(missing)} clips are missing. Run the script again to finish them."); return
    with open(os.path.join(OUT, "voices.json"), "w") as f:
        json.dump({"es": a.es, "en": a.en, "clips": len(JOBS)}, f)
    with zipfile.ZipFile(OUT + ".zip", "w", zipfile.ZIP_STORED) as z:
        for j in JOBS: z.write(os.path.join(OUT, j[3]), j[3])
        z.write(os.path.join(OUT, "voices.json"), "voices.json")
    print(f"All {len(JOBS)} clips ready: {os.path.abspath(OUT + '.zip')}")

asyncio.run(main())
